<script>(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;document.querySelectorAll('[data-counter]').forEach((el,index)=>{const target=Number(el.dataset.counter)||0;if(reduce||target===0){el.textContent=target.toLocaleString();return;}const duration=650,start=performance.now()+index*35;const tick=now=>{const progress=Math.max(0,Math.min(1,(now-start)/duration)),eased=1-Math.pow(1-progress,3);el.textContent=Math.round(target*eased).toLocaleString();if(progress<1)requestAnimationFrame(tick);};requestAnimationFrame(tick);});})();</script>
